// Static question bank, written from the STAT GR5702 (Fall 2026) slides, lectures and sample midterm.
// t = topic key, s = source, q = question, c = choices, a = index of correct choice,
// fx = keep choice order fixed (for "all/none of the above" style options), e = explanation.
const BANK = [
// ───────────────────────── EDA & PERCEPTION ─────────────────────────
{t:'eda', s:'01 EDA · 9/8', q:'Tukey (1977) famously described exploratory data analysis as:',
 c:['detective work','confirmatory hypothesis testing','a substitute for modeling','the final step of an analysis'], a:0,
 e:'"Exploratory data analysis is <b>detective work</b>." Tukey also said EDA "can never be the whole story, but nothing else can serve as the foundation stone — as the first step."'},
{t:'eda', s:'01 EDA · 9/8', q:'What is the main lesson of Anscombe\'s quartet?',
 c:['Datasets with nearly identical means, variances, correlations and regression lines can look completely different when graphed','Correlation implies causation when the sample size is large','Outliers never affect the regression line','Numerical summaries are sufficient as long as n > 10'], a:0,
 e:'The four datasets share the same numeric summary (means, variances, r, fitted line) but the graphs show a linear pattern, a curve, an outlier-driven line and a single leverage point. <b>Always look at the data.</b>'},
{t:'eda', s:'01 EDA · 9/8', q:'John Snow\'s 1854 cholera map is a classic example of:',
 c:['plotting observations in their spatial context to reveal a pattern (deaths clustered around the Broad St. pump)','using a pie chart to compare proportions','a time series showing seasonal patterns','an early mosaic plot'], a:0,
 e:'Snow plotted cholera deaths on a street map; the cluster around the <b>Broad Street pump</b> pointed to contaminated water.'},
{t:'eda', s:'02 Visualization · 9/10', q:'In class we evaluated graphs using four categories. Which of the following was NOT one of them?',
 c:['Wrong or misleading','Meaningless','Better options exist','Too many colors'], a:3,
 e:'The four categories: <b>1. Wrong or misleading, 2. Meaningless, 3. Better options exist, 4. Excellent.</b>'},
{t:'eda', s:'02 Visualization · 9/10', q:'Which statement about exploratory (EDA) vs. explanatory visualization is most accurate?',
 c:['They are not mutually exclusive, but the focus differs: exploring a dataset for yourself vs. presenting to an audience','Exploratory graphs should never be shared','Explanatory graphs must always be interactive','Exploratory graphs require titles and captions'], a:0,
 e:'Not mutually exclusive — visualizations that offer insight are likely to be shared. Still, the focus differs when you explore a dataset for the first time vs. present to a (possibly less technical) audience.'},
{t:'eda', s:'02 Visualization · 9/10', q:'What is the purpose of a "you-draw-it" graphic (e.g., the NYT drug overdose example)?',
 c:['It asks the viewer to form an expectation before revealing the data','It lets the viewer edit the underlying dataset','It replaces axes with annotations','It hides outliers until the viewer clicks'], a:0,
 e:'Viewers draw what they expect first, then see the real data — making comparison and interpretation more active.'},
{t:'eda', s:'02 Visualization · 9/10', q:'Data visualization was described as drawing on several fields. Which was NOT on the list?',
 c:['Psychology','Journalism','Graphic design','Accounting'], a:3,
 e:'Statistics, Graphic Design, Computer Science, Subject Expertise, Psychology and Journalism.'},
{t:'eda', s:'01 EDA · 9/8', q:'Which approach to a new dataset was recommended in the first lecture?',
 c:['Know what you\'re studying, start with single variables, then add variables','Start with the most complex multivariate plot to save time','Fit a model first and then plot residuals only','Remove all outliers before plotting'], a:0,
 e:'"Start with the data": understand where it came from and its limitations, start with single variables, then add variables. Experiment with different graphic forms based on data type.'},
{t:'eda', s:'PSet 1 · Ed post HW1', q:'A tuition dataset codes "not applicable" as -2. Before graphing tuition, the best practice is to:',
 c:['Recode the -2 values to NA so they are not treated as real tuition amounts','Leave them — they will show up as a useful spike','Replace them with the column mean','Multiply them by -1'], a:0,
 e:'Coded values are not measurements. Professor Robbins confirmed on Ed that changing the non-applicable -2 values to NA (and using descriptive factor labels) is fine. Otherwise you get an impossible spike below zero.'},

// ───────────────────────── GRAMMAR OF GRAPHICS / GGPLOT2 ─────────────────────────
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'Each ggplot2 layer consists of five components. Which is NOT one of them?',
 c:['geom','statistical transformation (stat)','position adjustment','theme'], a:3,
 e:'A layer = <b>geom + aesthetic mapping + data + stat + position</b>. Theme is a separate building block (Layers, Scales, Coord, Facet, Theme).'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'A single ggplot2 graph can have exactly ONE of which of the following?',
 c:['coordinate system','layer','scale','aesthetic mapping'], a:0,
 e:'Layers: no limit. Scales: one per aesthetic. <b>Coord: one.</b> Facet: one. Theme: one (sort of).'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'In <code>geom_histogram(color = "blue", fill = "cornflowerblue")</code>, color and fill are:',
 c:['settings (constants), not aesthetic mappings','aesthetic mappings because they are inside the geom','scales','stats'], a:0,
 e:'They are outside <code>aes()</code>, so they are <b>settings</b> — think constants. Only things inside <code>aes()</code> map a variable to a visual property (and get a scale + legend).'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'What does this code produce?<pre>ggplot(mtcars, aes(x = wt, y = mpg, color = am)) +\n  geom_point()</pre>(<code>am</code> is numeric 0/1.)',
 c:['A continuous color gradient (with a gradient legend), because am is numeric','Two distinct colors with a discrete legend','An error because color must be a factor','All points the same color'], a:0,
 e:'A numeric variable is <b>continuous</b> to ggplot2, so you get a gradient scale. Use <code>color = factor(am)</code> (or recode with <code>fct_recode</code>) to get two discrete colors.'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'In ggplot2, which data types are treated as <b>discrete</b>?',
 c:['factor, character and logical','numeric, double and integer','only factors','integer and factor'], a:0,
 e:'Continuous = any numeric type (num, dbl, int). Discrete = any non-numeric type (fct, chr, lgl). Many mistakes come from data in the wrong form, e.g. numbers stored as character.'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'What does <code>y = after_stat(density)</code> do in <code>ggplot(df, aes(x, y = after_stat(density))) + geom_histogram()</code>?',
 c:['Replaces the default after_stat(count) so the bars show density (total area = 1)','Adds a density curve on top of the histogram','Sorts the bins by density','Maps y to a column called density in df'], a:0,
 e:'Histograms compute <code>count</code> by default; <code>after_stat(density)</code> makes it a density histogram — needed e.g. to overlay <code>geom_density()</code> on the same scale.'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'Running this code gives "Cannot use `+` with a single argument." Why?<pre>ggplot(faithful, aes(x = eruptions))\n  + geom_histogram()</pre>',
 c:['The + starts a new line; it should end the previous line','geom_histogram needs a y aesthetic','faithful is not a data frame','aes must be named mapping ='], a:0,
 e:'Good practice: <b>end</b> lines with <code>+</code>. Starting a line with <code>+</code> makes R evaluate the first line as complete.'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'For a histogram, which is the appropriate use of color vs. fill?',
 c:['fill colors the inside of the bars (2D areas); color colors the bar borders','color colors the inside; fill colors the borders','They are interchangeable','fill only works with geom_point'], a:0,
 e:'<b>color</b> is for 0D/1D elements (points, lines, borders); <b>fill</b> is for 2D areas. (Base R <code>hist()</code> calls the border "border" and the fill "col".)'},
{t:'gg', s:'07 Univariate Categorical · 9/29', q:'You have a summary table with columns <code>knowledge</code> and <code>n</code> (counts already computed). Which code makes the bar chart?',
 c:['ggplot(mydata, aes(x = knowledge, y = n)) + geom_col()','ggplot(mydata, aes(x = knowledge, y = n)) + geom_bar()','ggplot(mydata, aes(x = knowledge)) + geom_bar()','ggplot(mydata, aes(x = n)) + geom_histogram()'], a:0,
 e:'Treat the counts as a value column and use <code>geom_col()</code> (= <code>geom_bar(stat = "identity")</code>). <code>geom_bar()</code> with both x and y errors: "stat_count() must only have an x or y aesthetic"; with only x it would count rows (each = 1).'},
{t:'gg', s:'07 Univariate Categorical · 9/29', q:'<code>geom_bar()</code> (default settings) uses which stat?',
 c:['count','identity','bin','density'], a:0,
 e:'<code>geom_bar()</code> → <code>stat = "count"</code> (one column of raw data). <code>geom_col()</code> → <code>stat = "identity"</code> (two columns: category and value).'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'What does <code>coord_flip()</code> do?',
 c:['Keeps the Cartesian coordinate system but switches x and y','Converts the plot to polar coordinates','Reverses the order of the x-axis','Flips the colors of the fill scale'], a:0,
 e:'Default coord is <code>coord_cartesian</code>; <code>coord_flip()</code> keeps Cartesian but switches x and y. (Don\'t overuse it.) To reverse an axis you would use <code>scale_x_reverse()</code>.'},
{t:'gg', s:'03 Grammar of Graphics · 9/15', q:'Which function would you use to <b>reverse the direction</b> of the x-axis?',
 c:['scale_x_reverse()','coord_flip()','fct_rev()','theme_reverse()'], a:0,
 e:'Scales connect data space to aesthetic space; <code>scale_x_reverse()</code> reverses a continuous x axis. (<code>fct_rev()</code> reverses factor level order, which is a data change.)'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'What happens with <code>ggplot(mtcars, aes(wt, mpg)) + geom_point() + scale_x_discrete(limits = c(-5, 15))</code>?',
 c:['Warning: continuous limits supplied to a discrete scale — the scale must match the data type','The x-axis is set to -5 to 15','wt is converted to a factor','The points are colored by wt'], a:0,
 e:'Scales must match the data type. wt is continuous, so you\'d use <code>scale_x_continuous(limits = c(-5, 15))</code>.'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'The default ggplot2 theme is <code>theme_grey(base_size = 11)</code>. What does <code>+ theme_grey(14)</code> do?',
 c:['Increases the font size of all text elements','Adds 14 grid lines','Changes the background to 14% grey','Sets the plot width to 14 inches'], a:0,
 e:'Increasing the base font size scales all text. Other built-ins: <code>theme_bw()</code>, <code>theme_classic()</code>, <code>theme_minimal()</code>, <code>theme_void()</code>, <code>theme_linedraw()</code>.'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'Who developed the "Grammar of Graphics" on which ggplot2 is based?',
 c:['Leland Wilkinson','John Tukey','William Cleveland','Antony Unwin'], a:0,
 e:'Leland Wilkinson (1944–2021). It\'s a theory, not a specific software — ggplot2 is one implementation (with slightly different syntax from the book).'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'ggplot2 and lattice are both built on which R graphics system?',
 c:['grid','base','htmlwidgets','plotly'], a:0,
 e:'The graphics engine supports two graphics systems: <b>base</b> and <b>grid</b>. ggplot2 and lattice are packages built on grid.'},
{t:'gg', s:'03 Grammar of Graphics · 9/10', q:'<code>geom_point()</code> with one continuous and one discrete variable mapped to x/y produces a:',
 c:['Cleveland dot plot','scatterplot','histogram','mosaic plot'], a:0,
 e:'geom_point requires x and y; both continuous = scatterplot; one continuous + one discrete = <b>Cleveland dot plot</b>.'},
{t:'gg', s:'12 Multivariate Categorical · 10/13', q:'To change a stacked bar chart (<code>geom_col()</code> with fill) into a grouped (side-by-side) bar chart, you change:',
 c:['the position adjustment from "stack" to "dodge"','the stat from "identity" to "count"','the coordinate system','the theme'], a:0,
 e:'Position is one of the 5 layer components: identity, jitter, dodge, stack (and fill). <code>position = "dodge"</code> places bars side by side.'},
{t:'gg', s:'Lecture 10/15', q:'What does <code>geom_col(position = "fill")</code> produce?',
 c:['A proportion (relative frequency) stacked bar chart where every bar has height 1','A grouped bar chart','Bars filled with a gradient','A bar chart with the gaps filled in'], a:0,
 e:'<code>position = "fill"</code> stacks and rescales each bar to 1. Watch out: the y-axis label will still say the original variable (e.g., "Freq") — fix it with <code>labs(y = "proportion")</code>.'},
{t:'gg', s:'03 Grammar of Graphics · 9/15', q:'In <code>ggplot(faithful, aes(x = eruptions)) + geom_histogram()</code>, where does geom_histogram get its data and mapping?',
 c:['It inherits them from the ggplot() call','It must be given its own data argument','From the global environment','From the theme'], a:0,
 e:'Geoms inherit data and mappings from <code>ggplot()</code>. You can override per layer (e.g., <code>geom_point(data = other_df)</code>).'},
{t:'gg', s:'03 Grammar of Graphics · 9/15', q:'<code>ggplot(df, aes(x, y, color = grp)) + geom_point(color = "red")</code> — what do you get?',
 c:['All points red; the setting overrides the inherited color mapping (no color legend)','Points colored by grp with a red outline','An error: color cannot be both mapped and set','Points colored by grp; "red" is ignored'], a:0,
 e:'A setting in the geom overrides the inherited mapping for that layer, so every point is red and no color legend is drawn.'},
{t:'gg', s:'Lecture 9/22', q:'You overlay raw data on boxplots with <code>geom_jitter()</code>. What does jitter do?',
 c:['Adds a small random displacement to points to reduce overplotting','Removes outliers','Sorts the points by value','Draws a density curve'], a:0,
 e:'Jitter is a position adjustment that adds small random noise so overlapping points become visible; it shows the underlying sample size behind each box.'},

// ───────────────────────── HISTOGRAMS ─────────────────────────
{t:'hist', s:'04 Univariate Continuous Pt1 · 9/17', q:'Which of the following is NOT one of the features we look for in univariate continuous data?',
 c:['Asymmetry','Heaping / rounding','Correlation','Gaps'], a:2,
 e:'What does the data show? Asymmetry, outliers, multimodality, gaps, heaping/rounding/spikes, impossibilities/errors. Correlation needs two variables.'},
{t:'hist', s:'04 Univariate Continuous Pt1 · 9/17', q:'In ggplot2, which way of controlling histogram bins was described as preferred?',
 c:['Choose the binwidth, e.g. geom_histogram(binwidth = 10)','Choose the number of bins, e.g. bins = 20','Always use the default 30 bins','Use the Sturges rule'], a:0,
 e:'Choose the number of bins (<code>bins = 20</code>) OR choose the binwidth — <b>binwidth is preferred</b>. Then set boundaries with <code>boundary</code> or <code>center</code>, or set all with <code>breaks</code>.'},
{t:'hist', s:'04 Univariate Continuous Pt1 · 9/17', q:'What does <code>geom_histogram(binwidth = 5, center = 2.5)</code> do?',
 c:['Sets the center of one bar at 2.5 (so bins are 0–5, 5–10, …)','Sets one bin boundary at 2.5','Sets the number of bins to 2.5','Centers the plot on x = 2.5'], a:0,
 e:'<code>center</code> picks the center of one bar; <code>boundary</code> picks one boundary. With binwidth 5, center = 2.5 is equivalent to boundary = 0.'},
{t:'hist', s:'04 Univariate Continuous Pt1 · 9/17', q:'Why does <code>geom_histogram(breaks = seq(0, 1000, 100))</code> require extra care?',
 c:['You need to know the range of the data so the breaks cover all values','breaks only works with discrete data','It silently changes the binwidth to 30','It cannot be combined with fill'], a:0,
 e:'Specifying all boundaries gives total control, but you need to know the range of the data.'},
{t:'hist', s:'04 Univariate Continuous Pt1 · 9/17', q:'In a <b>density</b> histogram, what does the AREA of each bar represent?',
 c:['The relative frequency (proportion) of observations in that bin','The count in that bin','The binwidth','The density times the count'], a:0,
 e:'Area = binwidth × density = relative frequency, and the areas sum to 1. density = relative frequency / binwidth.'},
{t:'hist', s:'04 Univariate Continuous Pt1 · 9/17', q:'Age groups in a census table have unequal widths (e.g., 20–24 and 25–34). Why is a <b>frequency</b> histogram of the counts misleading?',
 c:['Wider bins collect more people just because they are wider, so their bars look too tall; use a density histogram','Frequency histograms cannot show more than 10 bins','The bars will be sorted alphabetically','Counts are always wrong in census data'], a:0,
 e:'With unequal binwidths use density (= relative frequency / binwidth) so that bar <b>area</b> represents the fraction of observations. (This is the "27 year olds vs 6 year olds" sample midterm question.)'},
{t:'hist', s:'Lecture 9/17', q:'You histogram exam grades with binwidth 10. You want a 90 to land in the 90–100 bin, not the 80–90 bin. What should you use?',
 c:['Right-open bins: closed = "left", i.e. [90, 100)','Right-closed bins: closed = "right", i.e. (80, 90]','A larger binwidth','center = 90'], a:0,
 e:'With the default right-closed bins (a, b], a 90 falls into (80, 90]. In lecture: for grades you want it right open, <code>closed = "left"</code>, so 90s go into 90–100.'},
{t:'hist', s:'Lecture 9/17', q:'Histogram bin boundaries matter most when:',
 c:['data are discrete or rounded and many values fall exactly on boundaries','data are continuous with many decimal places','the sample size is very large','the histogram uses density'], a:0,
 e:'Values exactly on an edge go left or right depending on whether bins are right-closed or left-closed. With integer data, putting boundaries at .5 (centering bars on integers) avoids the issue.'},
{t:'hist', s:'Lecture 9/17', q:'What happens as you make histogram bins narrower?',
 c:['More detail is revealed but the histogram becomes more irregular/noisy','The histogram always becomes smoother','The total area changes','Outliers disappear'], a:0,
 e:'Narrow bins → finer detail but bumpy; wide bins → smooth but can hide features (e.g., rounding patterns, gaps). Always try more than one binwidth.'},
{t:'hist', s:'06 Univariate Continuous Pt3 · 9/24', q:'A histogram with binwidth 25 looks smooth, but with binwidth 1 there are tall spikes at every multiple of 5. This is evidence of:',
 c:['heaping / rounding','bimodality','a log-normal distribution','sampling error'], a:0,
 e:'Spikes at round numbers = heaping/rounding (people reporting rounded values). Small bins reveal it; large bins hide it.'},
{t:'hist', s:'04 Univariate Continuous Pt1 · 9/17', q:'In a cumulative frequency histogram of n = 250 observations, the height of the last bar is:',
 c:['250','1','the count in the last bin only','the binwidth'], a:0,
 e:'Cumulative frequency adds up counts from left to right, so the last bar equals the total n.'},
{t:'hist', s:'Sample midterm Q28 variant', q:'A histogram of finishing times in a race that includes both runners and walkers is most likely to be:',
 c:['bimodal','uniform','perfectly symmetric','left-skewed with no mode'], a:0,
 e:'Combining two groups with different typical values (like men and women\'s heights) produces two modes.'},
{t:'hist', s:'Sample midterm Q29 variant', q:'A histogram of household sizes shows an isolated tall spike at 99. The most likely explanation is:',
 c:['99 is a code for missing or unknown','one household is extremely large','the data were topcoded at 99','the binwidth is too large'], a:0,
 e:'Isolated spikes at "impossible" round values (99, 999, -2, …) are usually missing-value codes. Check the codebook! (Impossibilities/errors are one of the features we look for.)'},

// ───────────────────────── BOXPLOTS ─────────────────────────
{t:'box', s:'05 Univariate Continuous Pt2 · 9/22', q:'Which of the following CAN be read from a boxplot?',
 c:['the median','the mean','the sample size','whether the data are bimodal'], a:0,
 e:'Boxplots show the five-number summary (min, lower hinge, median, upper hinge, max) plus outliers. They <b>cannot</b> show means, sample size or modality (see sample midterm Q5).'},
{t:'box', s:'05 Univariate Continuous Pt2 · 9/22', q:'In Tukey\'s boxplot, the outlier fences are located at:',
 c:['1.5 × H-spread above the upper hinge and below the lower hinge','1.5 × standard deviation from the mean','2 × IQR from the median','the 5th and 95th percentiles'], a:0,
 e:'H-spread (fourth spread) = upper hinge − lower hinge. Fences: upper hinge + 1.5×H-spread, lower hinge − 1.5×H-spread. Points beyond the fences are drawn individually.'},
{t:'box', s:'05 Univariate Continuous Pt2 · 9/22', q:'Where do the whiskers of a boxplot end?',
 c:['At the most extreme data values that are still inside the fences','Exactly at the fences','At the min and max always','At the mean ± 2 SD'], a:0,
 e:'Whiskers extend to the most extreme <b>observations</b> within the fences, not to the fences themselves.'},
{t:'box', s:'05 Univariate Continuous Pt2 · 9/22', q:'Why might base R\'s <code>boxplot()</code> and ggplot2\'s <code>geom_boxplot()</code> draw slightly different boxes for the same data?',
 c:['Base R uses Tukey\'s hinges; ggplot2 uses quartiles (quantile()) and the IQR','ggplot2 uses the mean instead of the median','Base R uses 3 × IQR fences','ggplot2 removes outliers before computing the box'], a:0,
 e:'Tukey\'s original boxplot and base R use the hinge spread (fivenum). ggplot2 calculates quartiles and substitutes the IQR. E.g. mtcars$mpg: base R lower hinge 15.3, ggplot2 Q1 15.4.'},
{t:'box', s:'05 Univariate Continuous Pt2 · 9/22', q:'Using R\'s default <code>quantile()</code> (type 7), what is the 25th percentile of <code>10 20 30 40 50 60 70 80</code>?',
 c:['27.5','20','25','22.5'], a:0,
 e:'Type 7: h = (n−1)p = 7 × 0.25 = 1.75 → 20 + 0.75 × (30 − 20) = <b>27.5</b>. R has 9 quantile types; they give 20, 22.5, 24.2, 24.4, 25 or 27.5 here!'},
{t:'box', s:'05 Univariate Continuous Pt2 · 9/22', q:'In a variable-width boxplot, the width of each box is proportional to:',
 c:['√n (square root of the group size)','n','the IQR','the median'], a:0,
 e:'<code>varwidth = TRUE</code> makes box width proportional to √n.'},
{t:'box', s:'Lecture 9/22', q:'A boxplot flags several points as outliers. What should you do?',
 c:['Investigate them — a flagged point is a prompt for investigation, not an instruction to delete','Delete them before any further analysis','Replace them with the median','Increase the fence multiplier until they disappear'], a:0,
 e:'"What does it take to be an outlier?" — the fence rule is a convention. Outliers may be errors, special cases or the most interesting data.'},
{t:'box', s:'05 Univariate Continuous Pt2 · 9/22', q:'When comparing boxplots of fertility rate across many continents/groups, the groups should usually be:',
 c:['ordered by median (e.g., with fct_reorder)','ordered alphabetically','ordered by sample size only','placed in random order'], a:0,
 e:'Order matters for all graphs with categorical data. For nominal groups, order by a meaningful statistic like the median. Use a common scale.'},
{t:'box', s:'05 Univariate Continuous Pt2 · 9/22', q:'Which feature would a histogram reveal that a boxplot would hide?',
 c:['Bimodality','The median','Outliers beyond the fences','The range'], a:0,
 e:'Boxplots summarize with five numbers, so two distributions with very different shapes (e.g., bimodal vs unimodal) can have identical boxplots.'},
{t:'box', s:'Sample midterm Q31 variant', q:'In a boxplot, the median line sits exactly on the lower edge of the box and there is no lower whisker. The most plausible explanation is:',
 c:['Many values are tied (discrete data) so the minimum, lower hinge and median coincide','The data are normally distributed','The mean is below the median','The sample is very large and continuous'], a:0,
 e:'With discrete values or small samples, several summary statistics can be equal, producing boxes with missing whiskers or medians on an edge.'},
{t:'box', s:'Lecture 9/22', q:'Overlaying jittered points on boxplots is helpful mainly because it:',
 c:['makes the underlying sample (and its size) visible','removes the need for a y-axis','computes the mean','eliminates outliers'], a:0,
 e:'Boxplots hide n. Showing the raw (jittered) data reveals how many observations each box is based on.'},

// ───────────────────────── DENSITY & RIDGELINE ─────────────────────────
{t:'dens', s:'05 Univariate Continuous Pt2 · 9/22', q:'Decreasing the bandwidth of a kernel density estimate makes the curve:',
 c:['bumpier, with more local ups and downs','smoother','shift to the right','have a larger total area'], a:0,
 e:'Small bandwidth → more local variation; large bandwidth → smoother (sample midterm Q30). Compare several bandwidths before interpreting small bumps.'},
{t:'dens', s:'05 Univariate Continuous Pt2 · 9/22', q:'geom_density() places a kernel at every data point. The default kernel is ____ and the bandwidth acts like its ____.',
 c:['Gaussian; standard deviation (σ)','uniform; mean','Epanechnikov; median','triangular; range'], a:0,
 e:'Gaussian kernel; "bandwidth = 1 (think σ)".'},
{t:'dens', s:'Sample midterm Q10', q:'A density curve for data between 0 and 0.5 has a peak height of about 6. This is:',
 c:['fine — density values can exceed 1 because only the total area must equal 1','an error — densities cannot exceed 1','evidence that the data were not standardized','evidence the bandwidth is too small'], a:0,
 e:'Density is not probability. When x spans a short range, heights must be large so that the total area = 1.'},
{t:'dens', s:'05 Univariate Continuous Pt2 · 9/22', q:'Ridgeline plots show ______ better than multiple boxplots.',
 c:['modes / multimodality','medians','outliers','sample sizes'], a:0,
 e:'Ridgelines are stacked density curves, so they show shape — including multiple modes — which boxplots cannot (sample midterm Q11).'},
{t:'dens', s:'05 Univariate Continuous Pt2 · 9/22', q:'The ridgeline plot form was inspired by:',
 c:['Jocelyn Bell\'s 1967 radio pulsar data (popularized by Joy Division\'s album cover)','John Snow\'s cholera map','Anscombe\'s quartet','Florence Nightingale\'s rose diagram'], a:0,
 e:'Stacked traces of the first discovered radio pulsar → "joy plots". Package: <code>ggridges</code>.'},
{t:'dens', s:'05 Univariate Continuous Pt2 · 9/22', q:'Ridgeline plots are most useful for:',
 c:['comparing the distributions of a continuous variable across many categories on a common scale','showing the association between two categorical variables','showing a single variable\'s exact values','displaying missing data patterns'], a:0,
 e:'Many distributions stacked on a common horizontal scale; ordering the categories helps reveal changes.'},
{t:'dens', s:'05 Univariate Continuous Pt2 · 9/22', q:'A density curve of rents (which are never negative) extends below $0. Why?',
 c:['The kernels near the minimum spill past the boundary; check x-axis limits/boundaries','The data contain negative rents','The bandwidth is too small','geom_density always starts at 0'], a:0,
 e:'Kernel density estimates don\'t know about natural boundaries; they smooth beyond them (the "x-axis limits" slide). Same issue with 2D density contours ("watch out for boundaries").'},
{t:'dens', s:'06 Univariate Continuous Pt3 · 9/24', q:'To overlay a theoretical normal curve on a histogram for comparison, you must:',
 c:['use a density histogram (y = after_stat(density)) and the mean/sd of your data','use a count histogram','use the default mean = 0, sd = 1 always','set binwidth = 1'], a:0,
 e:'Check density vs count scaling and whether the curve\'s parameters match the data being compared.'},

// ───────────────────────── QQ PLOTS & NORMALITY ─────────────────────────
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'Which methods were presented to check whether data are normal?',
 c:['QQ plots, histograms/density curves, and statistical tests','only the Shapiro–Wilk test','only boxplots','mosaic plots'], a:0,
 e:'"Is the data normal?" → QQ plots, histograms/density curves, statistical tests. They provide complementary evidence.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'What is the null hypothesis of the Shapiro–Wilk test?',
 c:['The data are normally distributed','The data are not normally distributed','The mean is zero','The variance is one'], a:0,
 e:'H₀: normal. H₁: not normal. Small p-value → reject normality. A large p (e.g. .65) only means we <b>cannot reject</b> normality — not that there\'s a 65% chance it\'s normal.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'The Shapiro–Wilk statistic W:',
 c:['ranges from 0 to 1, with values near 1 indicating normality; the p-value depends on W and n','ranges from −1 to 1 like a correlation','is the p-value','is always 0.05'], a:0,
 e:'W from 0 to 1 (1 = normal). p-value depends on W <b>and n</b>: with very large n, tiny departures become "significant" — so look at the graphs too.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'Shapiro–Wilk on n = 5,000 observations gives p = 0.001, yet the QQ plot is almost perfectly straight. What\'s the best interpretation?',
 c:['With huge n the test detects trivial departures; the data are approximately normal for practical purposes','The data are definitely far from normal','The QQ plot must be wrong','The test is invalid for n > 30'], a:0,
 e:'p depends on n. Consider the graphical evidence as well as the test.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'In a normal QQ plot (theoretical quantiles on x, sample on y), right-skewed data typically show:',
 c:['a curve that bends upward (convex/U-shape): points above the line at both ends','a straight line','an S-shape with both tails flattened','a curve that bends downward (concave)'], a:0,
 e:'Right skew: the long upper tail rises above the line and the short lower tail also sits above it → convex "smile". Left skew is the mirror: concave "frown".'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'Data from a t distribution with 5 df (fat tails) produce a normal QQ plot that:',
 c:['is straight in the middle but falls below the line on the left and rises above it on the right','is perfectly straight','curves upward everywhere','flattens at both ends'], a:0,
 e:'Heavy tails: extreme values are more extreme than normal → the ends are steeper (S-shape). Light tails (uniform) are the opposite: the ends flatten.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'What does R\'s <code>ppoints(5)</code> return?',
 c:['Probability positions (≈ .119, .310, .5, .690, .881) used to choose which quantiles to compare','Five random normal numbers','The quartiles of the data','The five-number summary'], a:0,
 e:'ppoints() gives the probabilities at which sample and theoretical quantiles are compared in QQ/probability plots. Changing the probabilities changes which quantiles are paired.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'If you plot the quantiles of a large N(10, 2) sample against the quantiles of a large N(50, 10) sample, the points will:',
 c:['fall on a straight line (not y = x) because both are normal','form an S-shape','fall exactly on y = x','curve upward'], a:0,
 e:'Same distribution family, different location/scale → straight line with different slope/intercept. A QQ plot checks <b>shape</b>, not mean/SD.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'Which ggplot2 code draws a normal QQ plot with a reference line?',
 c:['ggplot(df, aes(sample = x)) + geom_qq() + geom_qq_line()','ggplot(df, aes(x = x)) + geom_qq()','ggplot(df, aes(x, y)) + geom_point() + geom_abline()','qqnorm(df) + geom_line()'], a:0,
 e:'geom_qq requires the <code>sample</code> aesthetic.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'Stem-and-leaf: "The decimal point is 1 digit(s) to the right of the |". The row <code>3 | 347</code> represents:',
 c:['33, 34, 37','3.3, 3.4, 3.7','330, 340, 370','347'], a:0,
 e:'Decimal point 1 digit right of | → stem = tens, leaf = units → 33, 34, 37. If it were 2 digits right, they\'d be 330, 340, 370.'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'A stem-and-leaf display in which every leaf is 0 or 5 suggests:',
 c:['rounding to the nearest 5 (heaping)','a uniform distribution','bimodality','outliers'], a:0,
 e:'Leaves only 0 and 5 → values rounded to multiples of 5 (as in sample midterm Q6, along with being unimodal and roughly symmetric).'},
{t:'norm', s:'06 Univariate Continuous Pt3 · 9/24', q:'Which R function produces a stem-and-leaf display?',
 c:['stem()','stemleaf()','geom_stem()','leaf()'], a:0, e:'Use <code>stem()</code> in base R.'},

// ───────────────────────── CATEGORICAL ─────────────────────────
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'How should bars be ordered for <b>nominal</b> data (e.g., favorite cuisine)?',
 c:['From highest to lowest count','Alphabetically','In the order of the data rows','Randomly'], a:0,
 e:'Nominal: sort by frequency (left→right or top→bottom), e.g. <code>fct_infreq()</code>. Ordinal: keep the logical order.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'How should bars be ordered for <b>ordinal</b> data (e.g., Novice, Intermediate, Advanced, Expert)?',
 c:['In the logical order of the categories','From highest to lowest count','Alphabetically','By the length of the label'], a:0,
 e:'Ordinal data have a fixed order: sort in the logical order (left→right, or starting at the bottom or top). Alphabetical would put Advanced before Novice.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'Which is an example where numbers are <b>nominal</b> rather than discrete?',
 c:['Zip codes','Number of children in a household','Number of cars owned','Number of siblings'], a:0,
 e:'"Sometimes numbers = nominal, not discrete." Zip codes are labels with no meaningful arithmetic.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'A column stored as <b>character</b> data (not factor) is mapped to x in a bar chart. In what order do the bars appear?',
 c:['Alphabetical','In order of the factor levels','By frequency','In the order they appear in the data'], a:0,
 e:'Character data: plotted alphabetically. Factor data: plotted in the order of the factor levels. <code>levels()</code> of a character vector is NULL.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'<code>df$temp</code> is a factor with levels "cold","warm","hot". What does <code>factor(df$temp, levels = c("Hot","Warm","Cold"))</code> return?',
 c:['All NA, because levels must match exactly (case-sensitive)','The same values reordered hot, warm, cold','An error','The values capitalized'], a:0,
 e:'Levels must match exactly. "Hot" ≠ "hot", so every value becomes <code>&lt;NA&gt;</code>.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'To change the order of factor levels you should use:',
 c:['factor(x, levels = c(...)) (or forcats functions), NOT levels(x) <- ...','levels(x) <- c(...)','sort(x)','as.character(x)'], a:0,
 e:'"Don\'t use levels() for setting levels!" Assigning to <code>levels()</code> <b>renames</b> levels (relabels data) rather than reordering them.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'Which forcats function orders a nominal factor by frequency, highest first?',
 c:['fct_infreq()','fct_rev()','fct_relevel()','fct_lump_n()'], a:0,
 e:'fct_infreq: by frequency. fct_reorder(x, y): by another variable (dot plots). fct_rev: reverse. fct_relevel: move levels by hand. fct_lump_n: keep top n + "Other".'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'For a Cleveland dot plot of states sorted by gas price, which function orders the states?',
 c:['fct_reorder(State, Price)','fct_infreq(State)','fct_rev(State)','fct_lump_n(State, 10)'], a:0,
 e:'<code>fct_reorder(x, y)</code> orders a nominal factor by another variable — the standard approach for dot plots.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'In a horizontal bar chart of ordinal data, the first level appears at the bottom. Which function puts it on top?',
 c:['fct_rev()','fct_infreq()','fct_lump_n()','fct_reorder2()'], a:0, e:'<code>fct_rev()</code> reverses the order — useful for horizontal bars.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'In the U.S. Births chart, "Under 15 years" was plotted at the end instead of the beginning. Which function fixes this?',
 c:['fct_relevel(x, "Under 15 years")','fct_infreq(x)','fct_lump_n(x, 1)','fct_rev(x)'], a:0, e:'<code>fct_relevel()</code> moves specific levels by hand.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'Which forcats function orders the levels by the y-value at the largest x (useful so the legend matches line ends)?',
 c:['fct_reorder2(x, a, b)','fct_reorder(x, y)','fct_infreq(x)','fct_relevel(x)'], a:0, e:'<code>fct_reorder2(x, a, b)</code>: order by b at the largest a — for multiple dots/lines.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'You have 40 categories and want to show the 8 most frequent plus a combined "Other". Which function?',
 c:['fct_lump_n(x, 8)','fct_infreq(x)','fct_other(x)','fct_collapse(x)'], a:0, e:'<code>fct_lump_n(x, n)</code> keeps the top n and lumps the rest into "Other".'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'Why might a Cleveland dot plot be better than a bar chart for average SAT scores between 400 and 700?',
 c:['Bars encode length so they need a zero baseline; dots encode position and don\'t','Dot plots can show counts and bar charts can\'t','Bar charts can\'t be sorted','Dot plots only work with nominal data'], a:0,
 e:'Bars must start at zero (truncating them distorts length). A dot\'s position can be read on any axis range, so differences between 400 and 700 are easier to see (sample midterm Q32).'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'A bar chart\'s y-axis starts at 50 instead of 0. Why is this a problem?',
 c:['Bar length encodes the value, so a truncated axis exaggerates differences','It isn\'t — bars can start anywhere','It hides the category labels','It changes the order of the bars'], a:0,
 e:'Bars need a zero baseline. If you want to zoom in, use a Cleveland dot plot instead.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'A bar chart can show either frequency counts or values. Which is a <b>value</b> bar chart?',
 c:['Average gas price for each of 6 states (two columns: State, Price)','Number of survey respondents at each knowledge level (one column)','Number of cars of each class in mpg','Count of flights per airline'], a:0,
 e:'Value bar chart: two columns (category, value) → <code>geom_col()</code>. Frequency bar chart: one column of raw data → <code>geom_bar()</code> counts it.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'Income categories end with "$200,000 or more". This open-ended top category is an example of:',
 c:['topcoding','bottom coding','binning error','missing data'], a:0,
 e:'"Other" and "or more" categories combine distinct observations. A topcoded bar is not a single measured value — interpret it differently.'},
{t:'cat', s:'07 Univariate Categorical · 9/29 · Sample midterm Q4 (updated key)', q:'According to the (corrected) sample midterm key, topcoding is acceptable when:',
 c:['the number of values in the top category or bin is small','the number of values in the top category or bin is large','never — it is discouraged due to privacy concerns','always'], a:0, fx:false,
 e:'The Q4 key was <b>updated</b> on Ed (Oct 17) to <b>c) acceptable if the number in the top category is small</b>. If many values pile into "or more", you lose a lot of information and the final bar becomes a conspicuous spike.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'When should you use <code>facet_grid(..., scales = "free_y", space = "free_y")</code> for a Cleveland dot plot?',
 c:['Sparingly — when facets have different numbers of categories so each panel only shows its own categories','Always — it is the default best practice','Only for continuous y variables','Never — it causes an error'], a:0,
 e:'Free y lets each panel show only its own categories and sizes panels by the number of categories. Use sparingly.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'Which is a good reason to choose a Cleveland dot plot over a bar chart?',
 c:['Many categories, values far from zero, or multiple values per category (multiple dots)','You need to show the sum of parts','You have only two categories','You want the bars to touch'], a:0,
 e:'Dot plots encode by position, handle many categories (sorted with fct_reorder), allow multiple dots per row and don\'t need a zero baseline.'},
{t:'cat', s:'07 Univariate Categorical · 9/29', q:'Which describes the main choices when graphing a single categorical variable?',
 c:['Which categories to plot and the order of the categories','Binwidth and boundary','Bandwidth and kernel','Fences and hinges'], a:0,
 e:'"Not a lot of options (bar plot, Cleveland dot plot)… main choices: which categories to plot, order of categories." Data cleaning takes more time.'},

// ───────────────────────── MISSING DATA ─────────────────────────
{t:'na', s:'08 Missing Values · 10/1', q:'By default, what does ggplot2 do with NA values in a categorical (discrete) variable in a bar chart?',
 c:['Keeps them and shows an NA bar','Drops them silently','Throws an error','Converts them to 0'], a:0,
 e:'Discrete default in ggplot2: <b>keep NAs</b> (shown as a separate bar, usually at the end).'},
{t:'na', s:'08 Missing Values · 10/1', q:'Why does <code>fct_relevel(kwhPerCap, NA)</code> fail to move the NA bar?',
 c:['NA is not a factor level; you must first make it an explicit level','fct_relevel only works with numeric data','NA must be lowercase','fct_relevel removes NAs'], a:0,
 e:'"Warning: 1 unknown level in f: NA". Make NA explicit first (<code>fct_explicit_na(x, "NA")</code> / <code>fct_na_value_to_level()</code>), then relevel "NA".'},
{t:'na', s:'08 Missing Values · 10/1', q:'After <code>animal2 &lt;- fct_explicit_na(animal, "NA")</code>, what does <code>is.na(animal2)</code> return for the formerly missing values?',
 c:['FALSE — "NA" is now a regular level, no longer a missing value','TRUE','NA','An error'], a:0,
 e:'That\'s why you shouldn\'t always make NAs explicit: R no longer recognizes them as missing.'},
{t:'na', s:'08 Missing Values · 10/1', q:'How many rows does <code>df |> drop_na()</code> keep?<pre>df\n  col1 col2 col3\n1    1   NA    8\n2    2    5    9\n3    3    6   10\n4    4    7   NA</pre>',
 c:['2','3','4','1'], a:0,
 e:'<code>drop_na()</code> (like <code>na.omit()</code>) keeps complete cases only, so rows 1 and 4 are removed.'},
{t:'na', s:'08 Missing Values · 10/1', q:'How many rows does <code>df |> drop_na(col2)</code> keep?<pre>df\n  col1 col2 col3\n1    1   NA    8\n2    2    5    9\n3    3    6   10\n4    4    7   NA</pre>',
 c:['3','2','4','1'], a:0, e:'Only rows with NA in <b>col2</b> are removed; row 4 (NA in col3) stays.'},
{t:'na', s:'Lecture 9/29', q:'A survey column contains the literal string "N/A" in some rows. How does R treat it?',
 c:['As a regular category, not as missing — is.na() is FALSE','As a missing value automatically','As zero','It causes a plotting error'], a:0,
 e:'Distinguish the string "N/A" from a true missing value NA. A bar chart can expose separate encodings that need consistent interpretation.'},
{t:'na', s:'08 Missing Values · 10/1', q:'Which is the base R equivalent of tidyverse\'s <code>drop_na()</code> (no arguments)?',
 c:['na.omit()','is.na()','complete()','na.rm = TRUE'], a:0, e:'Both remove all rows with any NAs (keep complete cases).'},

// ───────────────────────── SCATTERPLOTS & 2D DENSITY ─────────────────────────
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'Which is NOT a strategy for dealing with overplotting?',
 c:['Increasing the point size','Alpha blending','Open circles','Randomly sampling the data'], a:0,
 e:'Strategies: change the points (open circles, alpha blending, smaller circles), don\'t plot all points (sample, subset, remove outliers), transform to log scale, or use heatmaps/contours.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'Which features might be visible in a scatterplot? (Unwin p. 77)',
 c:['Associations, outliers, clusters, gaps, barriers, conditional relationships','Only linear correlation','Only causal relationships','Modes of categorical variables'], a:0,
 e:'Causal relationships (correlation ≠ causation — but still put the apparent dependent variable on y), associations, outliers, clusters, gaps, barriers (boundaries), conditional relationships.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'Gridlines on a scatterplot:',
 c:['make it easier to read individual values; removing them makes spatial patterns easier to detect','are always required','make outliers disappear','change the correlation'], a:0,
 e:'TFR vs GDP example: "easier to read individual values with gridlines / easier to detect spatial patterns without gridlines".'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'A regression of fertility on GDP has R² = 0.19. Why still make the scatterplot?',
 c:['The plot can reveal nonlinear patterns, clusters, outliers and boundaries that one number can\'t','A low R² means there is no relationship','Scatterplots are required for regression','To increase R²'], a:0,
 e:'"Why not use linear models instead?" — the model summarizes one aspect; the graph shows structure.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'Movie votes are extremely right-skewed. Which transformation helps the scatterplot of rating vs votes?',
 c:['scale_x_log10()','coord_flip()','scale_x_reverse()','facet_wrap(~votes)'], a:0, e:'Log scale spreads out the crowded low values.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'<code>ntile(votes, 10)</code> vs <code>cut(votes, 10)</code>:',
 c:['ntile gives (nearly) equal numbers of observations per bin; cut gives equal-width bins','both give equal widths','both give equal counts','ntile gives equal widths; cut gives equal counts'], a:0,
 e:'With skewed votes, <code>cut(votes, 10)</code> put 58,308 movies in the first bin and 2–3 in the last ones. <code>cut(votes, breaks = 10^(0:6))</code> uses custom (log) breaks.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'Which geom requires x, y AND z mappings?',
 c:['geom_contour()','geom_density_2d()','geom_hex()','geom_bin_2d()'], a:0,
 e:'geom_bin_2d, geom_hex, geom_density_2d: x and y (they compute counts/density). geom_contour and geom_tile need a supplied z (fill for tile) — e.g. after computing a kde with MASS::kde2d.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'All of the following can display the density of two-dimensional continuous data EXCEPT:',
 c:['a Cleveland dot plot','a hexbin plot','a square heatmap (2D histogram)','density contour lines'], a:0,
 e:'Cleveland dot plots are for one continuous variable across categories (sample midterm Q12).'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'<code>geom_bin_2d()</code> is also known as a:',
 c:['2D histogram (square heatmap of bin counts)','hexbin plot','density contour plot','scatterplot matrix'], a:0, e:'Square heatmap of bin counts = 2D histogram (default 30 bins).'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'<code>geom_density_2d()</code> draws contour lines based on:',
 c:['a 2D kernel density estimate computed from x and y','a z column you supply','the bin counts of hexagons','a linear regression'], a:0,
 e:'It uses a 2D KDE (MASS package). Filled version: <code>geom_density_2d_filled()</code>.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'Which pair of functions creates a scatterplot matrix?',
 c:['GGally::ggpairs() or lattice::splom()','geom_tile() or geom_raster()','ggparcoord() or parcoords()','mosaic() or mosaicplot()'], a:0,
 e:'Base R <code>plot()</code> / <code>pairs()</code>, <code>lattice::splom()</code>, <code>GGally::ggpairs()</code> (adds correlations and marginal distributions).'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'The Hermann grid illusion was mentioned in connection with:',
 c:['scatterplot matrices — the white gaps between dark panels create illusory dots','QQ plots','ridgeline plots','mosaic plots'], a:0, e:'Dark panels separated by white strips can produce phantom grey spots at intersections.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'An advantage of alpha blending is that it:',
 c:['shows where points are concentrated, because overlapping translucent points look darker','removes outliers','adds a regression line','reduces the number of points'], a:0, e:'Default alpha = 1. With alpha = .05 (and stroke = 0) dense regions emerge.'},
{t:'scat', s:'09a Dependency Relationships · 10/1', q:'Why use <code>ggplotly()</code> on a sampled scatterplot of movies?',
 c:['To hover and identify individual points (e.g., titles) interactively','To compute the correlation','To remove overplotting automatically','To fit a smoother'], a:0,
 e:'Interactive subsetting/hover makes a dense dataset easier to explore — but remember patterns in the sample aren\'t automatically conclusions about the full dataset.'},
{t:'scat', s:'Lecture 10/6', q:'In the iris data, a single pooled regression line differs from the lines fit separately by species. What does this illustrate?',
 c:['Group-specific relationships can differ from the pooled relationship — separate groups when appropriate','Species should be ignored','Regression lines are unreliable','Iris data are not continuous'], a:0,
 e:'Use color = Species to fit separate lines; the pooled relationship can even have the opposite sign (Simpson-like).'},

// ───────────────────────── FACETING & COMBINING ─────────────────────────
{t:'facet', s:'10a Faceting & Combining · 10/6', q:'Facets are also called:',
 c:['small multiples, panels, trellis, or lattice','layers','scales','themes'], a:0, e:'Faceting = small multiples / panels / trellis / lattice.'},
{t:'facet', s:'10a Faceting & Combining · 10/6', q:'Why is the default (shared scales) usually better than <code>facet_wrap(~Species, scales = "free")</code>?',
 c:['Common scales let you compare across panels','Free scales are not allowed with points','Free scales remove the legend','Shared scales make the panels larger'], a:0,
 e:'Free scales are "less useful": each panel gets its own axis range, so visual comparisons across panels mislead.'},
{t:'facet', s:'10a Faceting & Combining · 10/6', q:'"The exception that proves the rule": when is <code>scales = "free_x"</code> the better choice?',
 c:['When faceting on different variables (one panel per variable) measured in different units','When facets are levels of the same variable','When there are only two facets','Never'], a:0,
 e:'Italian wine example: pivot_longer the 27 measurements, then <code>facet_wrap(~variable, scales = "free_x")</code> — each variable has its own units, so a common x scale makes no sense.'},
{t:'facet', s:'10a Faceting & Combining · 10/6', q:'Which mapping options were recommended for <b>categorical</b> variables?',
 c:['color, facets (rows/columns), and maybe shape','x-axis only','size','alpha'], a:0,
 e:'Continuous: x, y (color and size "not so great"). Categorical: color, facets, shape (maybe).'},
{t:'facet', s:'10a Faceting & Combining · 10/6', q:'In <code>facet_grid(Type ~ variable)</code>:',
 c:['rows are Type, columns are variable','rows are variable, columns are Type','it makes a single panel','Type is mapped to color'], a:0, e:'<code>rows ~ columns</code>.'},
{t:'facet', s:'10a Faceting & Combining · 10/6', q:'You plot speed skiing data with color = Sex and facets by Event, then swap (color = Event, facets by Sex). Why does this matter?',
 c:['Elements in the same panel are easiest to compare, so swapping changes which comparison is emphasized','It doesn\'t — the plots are equivalent','Facets can only be used with Sex','Color cannot be used with Event'], a:0,
 e:'Decide which variable controls position, color or panel. The comparison you most care about should be within a panel.'},
{t:'facet', s:'10a Faceting & Combining · 10/6', q:'Best practice when adding variables to a plot:',
 c:['Start simple and add one variable at a time; don\'t overdo it','Map all variables at once','Always use at least 4 aesthetics','Use size for categorical variables'], a:0, e:'"Don\'t overdo it. Start simple. Add one variable at a time."'},
{t:'facet', s:'10a Faceting & Combining · 10/6', q:'How can you order facet panels by the number of observations in each nation?',
 c:['facet_wrap(~fct_infreq(Nation))','facet_wrap(~sort(Nation))','facet_wrap(~Nation, order = TRUE)','facet_wrap(~rev(Nation))'], a:0, e:'Apply the forcats function inside the facet formula.'},

// ───────────────────────── PARALLEL COORDINATES ─────────────────────────
{t:'pcp', s:'11 Multivariate Continuous · 10/6', q:'In a parallel coordinate plot, each line represents:',
 c:['one observation (case)','one variable','one group mean','one correlation'], a:0, e:'Each vertical axis = a variable; each line = one case connecting its values across axes.'},
{t:'pcp', s:'11 Multivariate Continuous · 10/6', q:'Between two adjacent axes, lines that mostly cross each other in an "X" pattern indicate:',
 c:['negative correlation','positive correlation','no correlation','missing data'], a:0,
 e:'Positive: lines roughly parallel (high stays high). Negative: lines cross (high → low). No correlation: lines go every which way.'},
{t:'pcp', s:'11 Multivariate Continuous · 10/6', q:'Why does axis order matter in a parallel coordinate plot?',
 c:['Only adjacent pairs of variables can be compared easily','Axes must be alphabetical','The first axis is always the dependent variable','Order affects the data values'], a:0,
 e:'Correlation/patterns are visible between neighboring axes. Interactive versions (parcoords) let you reorder axes.'},
{t:'pcp', s:'11 Multivariate Continuous · 10/6', q:'Standardizing a variable means:',
 c:['subtracting its mean and dividing by its standard deviation','dividing by the maximum','subtracting the minimum and dividing by the range','taking the log'], a:0,
 e:'(X − X̄)/σ — puts variables measured in different units on comparable scales. This is <code>ggparcoord</code>\'s default ("std").'},
{t:'pcp', s:'11 Multivariate Continuous · 10/13', q:'In <code>ggparcoord()</code>, <code>scale = "uniminmax"</code> means:',
 c:['each variable is linearly rescaled to [0, 1]: subtract min, divide by range','original units, no transformation','standardize to mean 0, SD 1','rank transform'], a:0,
 e:'uniminmax = <code>scales::rescale()</code> → [0,1]. globalminmax = original units. std (default) = standardize.'},
{t:'pcp', s:'11 Multivariate Continuous · 10/6', q:'Why scale variables before drawing a parallel coordinate plot of state.x77 (Population, Income, Illiteracy, Area…)?',
 c:['The variables are in very different units/ranges, so on a common raw axis most would be flattened','Scaling changes the correlations','ggplot2 requires it','To remove outliers'], a:0,
 e:'Area is in the hundreds of thousands while Illiteracy is ~1–3. Without rescaling, small-range variables are squashed.'},
{t:'pcp', s:'Sample midterm Q24', q:'Indicators in a parallel coordinate plot are each rescaled to range 0–1. What is lost?',
 c:['The ability to compare actual levels across indicators (which indicators have high values overall)','The ability to compare cases on a single indicator','The ordering of cases on each axis','The correlation between adjacent axes'], a:0,
 e:'Rescaling each axis separately hides absolute levels: every indicator now runs 0 to 1, so you can\'t tell which indicators are high in multiple districts (sample midterm Q24 answer b).'},
{t:'pcp', s:'11 Multivariate Continuous · 10/13', q:'What does <code>splineFactor</code> do in ggparcoord?',
 c:['Draws curved lines, making it easier to follow individual cases through crossings/ties','Adds a regression line','Changes the scaling','Adds alpha blending'], a:0, e:'Splines smooth the lines between axes; <code>alphaLines</code> handles overplotting; <code>groupColumn</code> colors by group.'},
{t:'pcp', s:'11 Multivariate Continuous · 10/13', q:'To draw a parallel coordinate plot with <code>geom_line()</code>, which preparation is required?',
 c:['Pivot the data to long form and use group = id so each case is one line','Convert all variables to factors','Compute the correlation matrix','Use coord_flip()'], a:0,
 e:'<code>pivot_longer()</code> the variables (keeping an id), optionally standardize by variable, then <code>geom_line(aes(x = name, y = value, group = id))</code>.'},
{t:'pcp', s:'11 Multivariate Continuous · 10/8', q:'Which graph is best for checking whether any movies top the charts on critics rating, audience rating AND box office simultaneously?',
 c:['parallel coordinate plot','scatterplot matrix','ridgeline plot','mosaic plot'], a:0,
 e:'Multivariate continuous data where you need to follow individual cases across all variables → PCP (sample midterm Q15). A scatterplot matrix shows pairs only.'},
{t:'pcp', s:'11 Multivariate Continuous · 10/8', q:'Highlighting the Russell Group universities in a parallel coordinate plot lets you:',
 c:['compare that group\'s profile across all variables with the rest of the data','remove the other universities','compute the group mean','sort the axes'], a:0, e:'Highlighting a group preserves context (other cases in grey) while showing the group\'s profile.'},
{t:'pcp', s:'11 Multivariate Continuous · 10/6', q:'A slope graph is:',
 c:['a parallel coordinate plot with just two axes','a scatterplot with a regression slope','a line chart of time series','a type of mosaic plot'], a:0,
 e:'Two parallel axes connected by lines — the 2-variable version of a PCP (vs perpendicular axes = scatterplot).'},
{t:'pcp', s:'11 Multivariate Continuous · 10/13', q:'Which is an <b>interactive</b> parallel coordinate implementation that supports brushing and axis reordering?',
 c:['parcoords::parcoords()','GGally::ggparcoord()','geom_line()','vcd::mosaic()'], a:0, e:'Static: geom_line(), GGally::ggparcoord(). Interactive: parcoords::parcoords() (htmlwidget).'},
{t:'pcp', s:'Lecture 10/13', q:'The SAT2010.csv columns read in as character (e.g., "s" for suppressed). What must you do before a PCP?',
 c:['Convert to numeric and investigate values that don\'t convert cleanly (they become NA)','Nothing — ggparcoord handles character data','Make them factors','Delete the column names'], a:0,
 e:'Imported columns may be strings. Check types and convert carefully; values like "s" become NA.'},

// ───────────────────────── MOSAIC & MULTIVARIATE CATEGORICAL ─────────────────────────
{t:'mosaic', s:'12 Multivariate Categorical · 10/15', q:'Which is the course definition of a mosaic plot?',
 c:['A filled rectangular plot (no white space) with consistent rows and columns, in which each small rectangle\'s area is proportional to the frequency of a unique combination of levels','Any plot made of rectangles, such as a treemap','A stacked bar chart with equal bar widths','A heatmap of correlations'], a:0,
 e:'Prof. Robbins\' definition. Treemaps are different: hierarchical data, packing algorithms, no consistent rows/columns, and they show values rather than frequency counts.'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/15', q:'A mosaic plot shows Sex (2 levels), Size (2 levels) and Food (5 levels) for alligators. How many tiles?',
 c:['20','9','10','25'], a:0, e:'One tile per unique combination: 2 × 2 × 5 = 20.'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'Best practice: the dependent variable in a mosaic plot should be:',
 c:['split last, horizontally, and used for the fill','split first, vertically','used for facets','omitted'], a:0,
 e:'Dependent variable split last and horizontally; fill = dependent variable; other variables split vertically (for 4 variables: H, V, V, H).'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'In a mosaic plot of a drug study (outcome: cured / partially cured / no change), where should "cured" (level of MOST interest) go?',
 c:['On the bottom, in the darkest (most noticeable) fill','On top, in the lightest fill','In the middle','It doesn\'t matter'], a:0,
 e:'Most important level is closest to the x-axis and darkest. Least interest (no change) → lightest on top (sample midterm Q17, confirmed on Ed).'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'In a two-variable mosaic plot, what pattern indicates NO association?',
 c:['The horizontal splits line up across columns (a grid, like Manhattan blocks)','A staircase pattern','Tiles of very different widths','Missing tiles'], a:0,
 e:'If the conditional proportions are the same for every column, the cuts align. Misalignment / a "staircase" signals association.'},
{t:'mosaic', s:'Lecture 10/15', q:'In a mosaic pairs plot, how do you identify the most strongly associated pair of variables?',
 c:['Find the panel with the biggest "staircase" pattern','Find the panel with the most tiles','Read the counts on the diagonal','Find the panel that looks like a regular grid'], a:0,
 e:'"What we\'re looking for is the biggest staircases… when it\'s looking like a Manhattan grid, that\'s little or no association." Don\'t try to read numbers off of it.'},
{t:'mosaic', s:'Lecture 10/15 · Ed (Q25)', q:'To decide whether program (undergrad vs grad) and binge drinking are associated, why is a mosaic plot better than a grouped bar chart?',
 c:['The mosaic shows conditional proportions directly (with area ∝ count); grouped bars emphasize raw frequencies','Grouped bar charts cannot show two variables','Mosaic plots show the mean','Grouped bar charts require continuous data'], a:0,
 e:'Grouped bar charts are good for reading off frequencies, not associations. Professor on Ed: "while you could infer association from a bar chart, a mosaic plot is a better choice."'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'In a stacked bar chart, which comparison across bars is EASIEST?',
 c:['The bottom segments (and the totals)','The middle segments','The top segments','All segments are equally easy'], a:0,
 e:'Bottom segments share a common baseline; totals too. Top/middle segments float at different heights, so they\'re hard to compare (sample midterm Q33).'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'Of 34,892 adults, 34.5% follow local news closely. If age and following are independent, the expected number of followers among 2,851 adults aged 18–29 is:',
 c:['≈ 984','≈ 428','≈ 1,867','≈ 2,851'], a:0,
 e:'Expected = group total × overall proportion = 2851 × 0.345 ≈ 984 (observed was only 428 — strong association).'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'The chi-square test of independence compares:',
 c:['observed counts with the counts expected if the variables were independent','means of two groups','the variance of each variable','the correlation of two continuous variables'], a:0,
 e:'H₀: the variables are independent. The test compares OBSERVED vs EXPECTED counts (local news example: X² = 997, df = 3, p < 2.2e-16).'},
{t:'mosaic', s:'Lecture 10/15', q:'Using vcd, <code>mosaic(Sat ~ Infl + Type, data = housing, direction = c("v","v","h"))</code>. In what order are the splits made?',
 c:['Infl, Type, then Sat','Sat, Infl, Type','Type, Infl, Sat','Sat, Type, Infl'], a:0,
 e:'The independent variables (right of ~) are split in order, and whatever is before the tilde (dependent) is split <b>last</b>. That\'s why the direction vector (v, v, h) isn\'t in formula order.'},
{t:'mosaic', s:'Lecture 10/15', q:'For <code>highlighting_fill</code> in vcd::mosaic with Satisfaction (Low/Medium/High) as the dependent variable, how many colors do you need?',
 c:['3 — the number of levels of the dependent variable','4 — one per housing type','12','1'], a:0,
 e:'Number of factor levels in the dependent variable. Using the wrong number won\'t always error — it silently gives a wrong graph.'},
{t:'mosaic', s:'Lecture 10/15', q:'With four variables, the typical split directions are:',
 c:['horizontal, vertical, vertical, horizontal','vertical, vertical, vertical, horizontal','horizontal, horizontal, vertical, vertical','all vertical'], a:0,
 e:'"The go-to with four is: first cut horizontal, then vertical, then vertical, then horizontal." With three: V, V, H.'},
{t:'mosaic', s:'Lecture 10/15', q:'In a mosaic plot, how can you tell which variable was split <b>before</b> another?',
 c:['The earlier split forms contiguous blocks (one label per level); the later variable\'s labels repeat within each block','The earlier variable always has more levels','The earlier variable is always on the y-axis','You can\'t tell'], a:0,
 e:'Housing example: four distinct blocks of Type, and Low/Medium/High influence repeated within each → Type was split before Influence. (Don\'t rely only on counting labels.)'},
{t:'mosaic', s:'Lecture 10/15', q:'Where should you place the most influential independent variable in the split order?',
 c:['Right before the dependent variable (last of the independent splits)','First','It must be the fill','Anywhere — order doesn\'t matter'], a:0,
 e:'Not a hard rule, but placing it right before the dependent variable lets you see its relationship with the dependent variable within every combination of the others.'},
{t:'mosaic', s:'Lecture 10/15', q:'A spine plot is:',
 c:['a mosaic plot with straight parallel cuts in one dimension and only one variable cutting in the other','a boxplot with a notch','a parallel coordinate plot with two axes','a stacked bar chart with equal widths'], a:0, e:'It\'s "just a mosaic plot, nothing special there."'},
{t:'mosaic', s:'Lecture 10/15', q:'A "same bin width" mosaic plot (all column widths equal) is equivalent to:',
 c:['a relative frequency (proportion) stacked bar chart','a grouped bar chart','a treemap','a Cleveland dot plot'], a:0, e:'Two forms meet: make the mosaic same-binwidth and the stacked bars proportions, and you get the same chart.'},
{t:'mosaic', s:'Lecture 10/15', q:'What is a drawback of a proportion (relative frequency) stacked bar chart compared with a mosaic plot?',
 c:['You lose the information about how many observations are in each group','It cannot show more than two categories','It requires continuous data','It cannot use color'], a:0,
 e:'Mosaic widths show group sizes. Proportion charts hide them — though when group sizes are wildly different, proportions can be more readable.'},
{t:'mosaic', s:'Lecture 10/15', q:'Airline A has a higher overall delay rate than airline B, yet B has a higher delay rate at every airport. What explains it?',
 c:['The airlines fly very different mixes of airports (A flies mostly from a rainy, high-delay airport) — Simpson\'s paradox','A calculation error','B has more flights overall','Delays are random'], a:0,
 e:'Mosaic plots make it clear: tile sizes show Alaska flying mostly from Seattle (rain, delays) and America West mostly from Phoenix. The airport drives the delays; airlines are associated with airports.'},
{t:'mosaic', s:'Lecture 10/15', q:'Your data have one row per person (cases). Which code converts them to counts (a frequency column)?',
 c:['group_by(...) |> summarize(Freq = n())','pivot_longer()','as.data.frame(table) only','drop_na()'], a:0,
 e:'Cases → counts: group_by + summarize (or count()). Table class → data frame: as.data.frame(). Wide → long: pivot_longer(). Going from counts back to cases is hard (you must repeat rows).'},
{t:'mosaic', s:'Lecture 10/15', q:'Your data have a frequency column (each row is a combination of categories with Freq). For a mosaic plot, what must happen?',
 c:['The Freq column must be used as the weight/count so each row contributes its frequency to the area','Each row should be treated as one observation','Freq should be dropped','Freq should be mapped to color'], a:0, e:'A row is not automatically one observation; the counts must contribute to the mosaic areas.'},
{t:'mosaic', s:'Lecture 10/15', q:'A diverging stacked bar chart is designed for:',
 c:['ordinal (Likert-type) data whose first and last categories are polar opposites','nominal data with large frequency differences','time series data','continuous data with outliers'], a:0,
 e:'It centers the neutral category on zero so agreement extends one way and disagreement the other (sample midterm Q1).'},
{t:'mosaic', s:'Lecture 10/15', q:'In a diverging stacked bar chart, when should you consider removing the neutral category?',
 c:['When "neutral" really means "don\'t know / no opinion" rather than a middle opinion','Always','Never','When there are more than three categories'], a:0,
 e:'"About right" between "too far" and "not far enough" is a real opinion — keep it and split it around zero. But "neutral" about a candidate you\'ve never heard of isn\'t an opinion — take it out.'},
{t:'mosaic', s:'Lecture 10/15', q:'In the occupational mobility mosaic (father\'s vs son\'s occupation), which is the dependent variable and therefore the fill?',
 c:['Son\'s occupation','Father\'s occupation','Frequency','Country'], a:0,
 e:'The assumption is that the father\'s occupation affects the son\'s, not the other way around, so Son is split last and used for fill.'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'A grouped bar chart of Father × Son occupation is best for:',
 c:['reading off specific frequencies','seeing the association between the variables','showing proportions within each father group','seeing the total for each son group'], a:0,
 e:'"This kind of chart would be really good if what you care about is reading off frequencies" — not associations.'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'What does a mosaic plot look like under a perfectly deterministic relationship (e.g., every son has the father\'s occupation)?',
 c:['Each column is a single filled tile of a different level — a full staircase','A regular grid with aligned cuts','All tiles the same size','Empty'], a:0, e:'Extreme hypothetical ("caste system"): each column contains only one level of the dependent variable.'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'The mosaic of Favorite flavor vs Age split on Age first looks very different from one split on Favorite first. Should they lead to the same conclusion about association?',
 c:['Yes — the arrangement differs but both show the same (non-)association','No — association depends on split order','Only if both variables are ordinal','Only for 2×2 tables'], a:0,
 e:'Unlike a flipped scatterplot, the mosaic looks very different, but if one shows no association the other will too — "just arranged a little differently".'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/13', q:'For three categorical variables, which display is often a good alternative to a mosaic plot for reading frequencies?',
 c:['Grouped/stacked bar chart with facets, or a Cleveland dot plot with color','Parallel coordinate plot','QQ plot','Ridgeline plot'], a:0,
 e:'Frequency → bar charts / Cleveland dot plots (color + facets). Proportion/association → mosaic plots.'},
{t:'mosaic', s:'12 Multivariate Categorical · 10/15', q:'Which statement about color in mosaic plots is correct?',
 c:['Use an ordered (sequential) palette for an ordinal dependent variable, with the most important level darkest','Use a different random color for every tile','Color should encode the first split','Avoid any legend'], a:0,
 e:'Use deliberate category colors and ordered palettes (e.g. <code>RColorBrewer::brewer.pal(3, "Greens")</code>). Make sure the legend and shading make the response order clear.'},
];
